INSERT INTO "cotisation_campagnes" ("id", "user_id", "titre", "description", "image", "montant_objectif", "date_limite", "statut", "commentaire_admin", "reviewed_at", "created_at") VALUES (1, NULL, 'Festival Nuits d''Abidjan 2026', 'Aidez-nous à organiser la plus grande édition du Festival Nuits d''Abidjan : scène géante, sonorisation, éclairage et artistes internationaux. Chaque contribution compte !', 'https://images.unsplash.com/photo-1470229722913-7c0e2dbbafd3?auto=format&fit=crop&w=800&q=80', 2500000.00, '2026-10-14', 'active', NULL, NULL, '2026-08-30 03:01:51');
