INSERT INTO "cotisation_campagnes" ("id", "user_id", "titre", "description", "image", "montant_objectif", "date_limite", "statut", "commentaire_admin", "reviewed_at", "created_at") VALUES (3, NULL, 'Grand Gala de Fin d''Année', 'Participez au financement du Grand Gala de Fin d''Année au Palais de la Culture : orchestre live, buffett et animation. Les contributeurs recevront des invitations VIP.', 'https://images.unsplash.com/photo-1519671482749-fd09be7ccebf?auto=format&fit=crop&w=800&q=80', 5000000.00, '2026-11-28', 'active', NULL, NULL, '2026-08-30 03:01:51');
